#!/usr/bin/env python3
from __future__ import annotations

import base64
import hashlib
import py_compile
import shutil
from datetime import datetime
from pathlib import Path

TARGET_REL = "scripts/run_bc_dpg_v3_ablation.py"
CONTENT_B64 = ''
EXPECTED_SHA256 = '5cc5787d75e31be6ce9248bec34f2f671a088a115a8219b21b501d815af1d01d'


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> None:
    project_root = Path(__file__).resolve().parent
    target = project_root / TARGET_REL
    required = [
        project_root / "training" / "train_target_protected_scan_calibrator_ablation.py",
        project_root / "scripts" / "summarize_bc_dpg_v3_ablation.py",
        target,
    ]
    missing = [
        str(path.relative_to(project_root))
        for path in required
        if not path.is_file()
    ]
    if missing:
        print("[错误] 请把本安装器直接放在 balloon_radar_project 项目根目录。")
        print("缺少以下文件：")
        for item in missing:
            print(f"  - {item}")
        raise SystemExit(2)

    content = base64.b64decode(CONTENT_B64)
    actual_hash = sha256_bytes(content)
    if actual_hash != EXPECTED_SHA256:
        raise RuntimeError(
            f"内置文件哈希异常：{actual_hash} != {EXPECTED_SHA256}"
        )

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = (
        project_root
        / "backups"
        / f"bc_dpg_v3_ablation_runner_fix_v2_{timestamp}"
        / TARGET_REL
    )
    backup.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(target, backup)

    target.write_bytes(content)
    target.chmod(0o755)
    py_compile.compile(str(target), doraise=True)

    installed_hash = sha256_bytes(target.read_bytes())
    if installed_hash != EXPECTED_SHA256:
        raise RuntimeError("安装后的文件哈希校验失败。")

    print("=" * 76)
    print("BC-DPG v3 消融批量入口续跑修复安装完成")
    print(f"更新文件：{target.relative_to(project_root)}")
    print(f"原文件备份：{backup.relative_to(project_root)}")
    print(f"SHA256：{installed_hash}")
    print("")
    print("现在可直接重新执行原命令，无需 --overwrite：")
    print(
        "python scripts/run_bc_dpg_v3_ablation.py "
        "--folds 1 4 --modes core --smoke"
    )
    print("=" * 76)


if __name__ == "__main__":
    main()
